// Acknowledgements: Yap's own copyright, and the open-source packages it is built with, each
// with its licence. The list is generated by `npm run licenses` (scripts/make-licenses.mjs)
// into src/data/third-party-licenses.json; never edit that file by hand.

import Ionicons from '@expo/vector-icons/Ionicons';
import { router } from 'expo-router';
import { useState } from 'react';
import { FlatList, Linking, Pressable, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { AppText } from '@/components/ui/app-text';
import { Button, IconButton } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { ScreenHeader } from '@/components/ui/screen-header';
import { TopBar } from '@/components/ui/top-bar';
import licenses from '@/data/third-party-licenses.json';
import { useTheme } from '@/theme';

type Package = (typeof licenses.packages)[number];

export default function Acknowledgements() {
  const { colors, layout, size, spacing } = useTheme();
  // The package whose licence text is open; one at a time keeps the list short.
  const [openKey, setOpenKey] = useState<string | null>(null);

  const renderPackage = ({ item }: { item: Package }) => {
    const key = `${item.name}@${item.version}`;
    const open = openKey === key;
    let title = item.name;
    if (item.version) {
      title = `${item.name} ${item.version}`;
    }

    let licenseText = 'No licence text was published with this package. See its repository for details.';
    if (item.textIndex >= 0) {
      licenseText = licenses.texts[item.textIndex]!;
    }

    return (
      <Card padding="compact">
        <Pressable
          accessibilityRole="button"
          accessibilityLabel={`${title}, ${item.license} licence`}
          accessibilityHint={open ? 'Hides the licence text' : 'Shows the licence text'}
          accessibilityState={{ expanded: open }}
          onPress={() => setOpenKey(open ? null : key)}
          style={[styles.row, { gap: spacing.md, minHeight: layout.touchTarget }]}>
          <View style={styles.flex}>
            <AppText variant="bodyStrong">{title}</AppText>
            <AppText variant="caption" color="textSecondary">
              {item.license}
            </AppText>
          </View>
          <Ionicons name={open ? 'chevron-up' : 'chevron-down'} size={size.iconMedium} color={colors.textSecondary} />
        </Pressable>
        {open && (
          <View style={{ gap: spacing.sm, marginTop: spacing.sm }}>
            <AppText variant="caption" color="textSecondary" selectable>
              {licenseText}
            </AppText>
            {Boolean(item.repository) && (
              <Button
                label="Open the project's page"
                variant="ghost"
                size="compact"
                onPress={() => void Linking.openURL(item.repository)}
              />
            )}
          </View>
        )}
      </Card>
    );
  };

  return (
    <SafeAreaView style={[styles.flex, { backgroundColor: colors.background }]}>
      <FlatList
        contentContainerStyle={{
          paddingHorizontal: layout.screenPadding,
          paddingTop: spacing.lg,
          paddingBottom: spacing.xxl,
          gap: spacing.sm,
        }}
        data={licenses.packages}
        keyExtractor={(item) => `${item.name}@${item.version}`}
        ListHeaderComponent={
          <View style={{ gap: spacing.sm, marginBottom: spacing.sm }}>
            <TopBar leading={<IconButton icon="arrow-back" label="Back" onPress={() => router.back()} />} />
            <ScreenHeader
              title="Acknowledgements"
              subtitle="Yap is © 2026 Samar Khajuria. All rights reserved. The app icon, logo and the Yap cat are original artwork made for Yap."
            />
            <AppText color="textSecondary">
              Yap is built with the open-source software below. Thank you to everyone who made it. Tap a package to read
              its licence.
            </AppText>
          </View>
        }
        renderItem={renderPackage}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  row: { flexDirection: 'row', alignItems: 'center' },
});
